import { Component, inject } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MAT_DIALOG_DATA, MatDialog, MatDialogModule, MatDialogRef } from '@angular/material/dialog';

@Component({
  selector: 'app-confirm-dialog',
  standalone: true,
  imports: [MatDialogModule, MatButtonModule],
  template: `
    <h2 mat-dialog-title>Confirm</h2>
    <mat-dialog-content>{{ data.message }}</mat-dialog-content>
    <mat-dialog-actions>
      <button mat-button (click)="dialogRef.close(false)">Cancel</button>
      <button mat-button (click)="dialogRef.close(true)">OK</button>
    </mat-dialog-actions>
  `,
})
export class ConfirmDialogComponent {
  dialogRef = inject(MatDialogRef<ConfirmDialogComponent>);
  data = inject<{ message: string }>(MAT_DIALOG_DATA);
}

@Component({
  selector: 'app-example',
  standalone: true,
  imports: [MatButtonModule],
  template: `<button mat-button (click)="openDialog()">Open</button>`,
})
export class ExampleComponent {
  private dialog = inject(MatDialog);

  openDialog(): void {
    const ref = this.dialog.open(ConfirmDialogComponent, { data: { message: 'Are you sure?' } });
    ref.afterClosed().subscribe((confirmed) => console.log(confirmed));
  }
}
